insert into puzzles (puzzle_number, publish_date, film_id, state) values (1, '2026-10-24', (select id from films where title_normalized = 'home alone' and release_year = 1990), 'scheduled') on conflict (puzzle_number) do nothing;
insert into puzzle_clues (puzzle_id, position, kind, body) values
  ((select id from puzzles where puzzle_number = 1), 1, 'villain_defense', 'My clients were just working through the holidays. They walked into what they thought was an empty house and got a blowtorch, a tarantula and a paint can to the face. Who is the real victim here?'),
  ((select id from puzzles where puzzle_number = 1), 2, 'villain_identity', 'Two burglars who call themselves the Wet Bandits.'),
  ((select id from puzzles where puzzle_number = 1), 3, 'prosecution', 'They spent weeks casing every house on the street and then targeted the one where an eight-year-old boy had been left alone.'),
  ((select id from puzzles where puzzle_number = 1), 4, 'genre_year', 'Christmas family comedy, 1990'),
  ((select id from puzzles where puzzle_number = 1), 5, 'plot_summary', 'A boy accidentally left behind when his family flies to Paris for Christmas defends his house from two burglars.')
